package org.example.backend.service;
import org.example.backend.service.gateway.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class IotGatewayCommandBehaviorTest {
    final GatewayAdapterRegistry registry=mock(GatewayAdapterRegistry.class);
    final GatewayAdapter adapter=mock(GatewayAdapter.class);
    final Map<String,Object> log=Map.of("id",9,"resultStatus","mock_success");
    JdbcTemplate jdbc(Map<String,Object> point){return mock(JdbcTemplate.class,call->{if(call.getMethod().getName().equals("queryForList")){String sql=call.getArgument(0);return sql.contains("iot_gateway_point")?(point.isEmpty()?List.of():List.of(point)):List.of(log);}return RETURNS_DEFAULTS.answer(call);});}
    @Test void executesConfiguredPointAndPersistsCanonicalCommandAudit(){
        Map<String,Object> point=Map.of("pointId",3L,"gatewayId",4L,"gatewayCode","GW1","protocolType","http","gatewayAddress","http://gateway.test","pointCode","P1","requestPath","/switch","authType","token");JdbcTemplate jdbc=jdbc(point);IotGatewayCommandService service=new IotGatewayCommandService(jdbc,registry);when(registry.resolve("http",true)).thenReturn(adapter);when(adapter.sendCommand(any())).thenAnswer(call->GatewayCommandResult.mockSuccess(call.getArgument(0),Map.of("state","on")));
        Map<String,Object> result=service.execute(Map.of("id",1L,"labId",2L,"iotCode","IOT1","deviceType","light","configured",1),Map.of("action","power-on","payload",Map.of("value",1),"operatorId","7","operatorName","管理员"));assertEquals(log,result);verify(adapter).sendCommand(argThat(request->request.gatewayId().equals(4L)&&request.labId().equals(2L)&&request.commandType().equals("power-on")&&request.payload().equals(Map.of("value",1))));var insert=mockingDetails(jdbc).getInvocations().stream().filter(call->call.getMethod().getName().equals("update")).findFirst().orElseThrow();Object[] args=insert.getArguments();assertTrue(args[1].toString().startsWith("IOT-CMD-"));assertEquals("{\"value\":1}",args[9]);assertTrue(Arrays.asList(args).contains("mock"));assertTrue(Arrays.asList(args).contains(7L));
    }
    @Test void missingPointUsesUnconfiguredMockAndRequestLabOverridesDeviceLab(){JdbcTemplate jdbc=jdbc(Map.of());IotGatewayCommandService service=new IotGatewayCommandService(jdbc,registry);when(registry.resolve("tcp",false)).thenReturn(adapter);when(adapter.sendCommand(any())).thenAnswer(call->GatewayCommandResult.realGatewayNotConfigured("tcp_gateway",call.getArgument(0)));assertEquals(log,service.execute(Map.of("id","1","labId",2,"configured","yes","protocol","tcp"),Map.of("labId","3","commandKey","open","payload","invalid")));verify(adapter).sendCommand(argThat(request->request.labId().equals(3L)&&request.action().equals("open")&&request.payload().isEmpty()));var insert=mockingDetails(jdbc).getInvocations().stream().filter(call->call.getMethod().getName().equals("update")).findFirst().orElseThrow();assertTrue(Arrays.asList(insert.getArguments()).contains("gateway"));}
    @Test void invalidLabOrActionCannotSendCommands(){IotGatewayCommandService service=new IotGatewayCommandService(jdbc(Map.of()),registry);assertThrows(IllegalArgumentException.class,()->service.execute(Map.of(),Map.of()));assertThrows(IllegalArgumentException.class,()->service.execute(Map.of("labId","bad"),Map.of()));assertThrows(IllegalArgumentException.class,()->service.execute(Map.of("labId",1),Map.of()));verifyNoInteractions(registry,adapter);}
    @Test void absentDeviceIdentitySkipsPointLookupAndPayloadKeysAreNormalized(){JdbcTemplate jdbc=jdbc(Map.of());IotGatewayCommandService service=new IotGatewayCommandService(jdbc,registry);when(registry.resolve("mock",false)).thenReturn(adapter);when(adapter.sendCommand(any())).thenAnswer(call->GatewayCommandResult.mockSuccess(call.getArgument(0),Map.of()));Map<Object,Object> payload=new HashMap<>();payload.put(7,"value");payload.put(null,"ignored");service.execute(Map.of("labId",1,"configured",false),Map.of("action","on","payload",payload));verify(adapter).sendCommand(argThat(request->request.iotDeviceId()==null&&request.payload().equals(Map.of("7","value"))));assertEquals(1,mockingDetails(jdbc).getInvocations().stream().filter(call->call.getMethod().getName().equals("queryForList")).count());}
}
